/// 5-digit pairing code generated by the game (`core_remoteController`).
///
/// Accepted inputs, because the QR content already changed once:
///   - Beam-RemotePlus panel QR: `beamremoteplus://pair?code=54688&host=192.168.1.20#54688`
///     (with the PC address, so no broadcast is needed)
///   - BeamNG >= 0.39 QR: `https://play.google.com/...remotecontrol#54688`
///   - older QR: `<text>#<code>`
///   - a code typed by hand.
class PairingCode {
  final String securityCode;

  /// IPv4 address of the PC, from the panel QR code (null otherwise).
  final String? host;

  const PairingCode(this.securityCode, {this.host});

  static final RegExp _ipv4 = RegExp(r'^\d{1,3}(\.\d{1,3}){3}$');

  /// The host of a `beamremoteplus://pair` URI, if valid.
  static String? _hostOf(String raw) {
    final uri = Uri.tryParse(raw);
    if (uri == null || uri.scheme != 'beamremoteplus' || uri.host != 'pair') return null;
    final host = uri.queryParameters['host'];
    return host != null && _ipv4.hasMatch(host) ? host : null;
  }

  static final RegExp _validCode = RegExp(r'^\d{4,6}$');
  static final RegExp _digits = RegExp(r'\d{4,6}');

  /// 1. text after the last `#`; 2. otherwise the first run of 4-6 digits.
  static PairingCode? tryParse(String raw) {
    final trimmed = raw.trim();
    if (trimmed.isEmpty) return null;

    String? candidate;
    final hashIndex = trimmed.lastIndexOf('#');
    if (hashIndex >= 0 && hashIndex < trimmed.length - 1) {
      candidate = trimmed.substring(hashIndex + 1).trim();
    }
    if (candidate == null || !_validCode.hasMatch(candidate)) {
      candidate = _digits.firstMatch(trimmed)?.group(0);
    }
    if (candidate == null || !_validCode.hasMatch(candidate)) return null;
    return PairingCode(candidate, host: _hostOf(trimmed));
  }
}
